  aiResolve: {
    parameters: {
      query: {
        /** @description Full short URL (e.g. https://f.elido.me/abc) */
        url: string;
      };
      header?: never;
      path?: never;
      cookie?: never;
    };
    requestBody?: never;
    responses: {
      /** @description Structured metadata about the short link destination */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": {
            /** @example https://schema.org */
            "@context"?: string;
            /** @example WebPage */
            "@type"?: string;
            /** Format: uri */
            shortUrl: string;
            /** Format: uri */
            destinationUrl: string;
            /** @description Page title */
            name?: string;
            description?: string;
            /** Format: uri */
            image?: string;
            siteName?: string;
            /** @enum {string} */
            status: "active" | "disabled";
            safety: {
              score?: number;
              /** @enum {string} */
              status?: "clean" | "suspect" | "blocked";
            };
            category?: string;
          };
        };
      };
      /** @description Missing or invalid url parameter */
      400: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description Short link not found */
      404: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
    };
  };
